    private static readonly int[][] rowEntries = BuildRowEntries();

    public static int[] RowEntries(int row, int value) => rowEntries[row * 256 + value];

    private static int[][] BuildRowEntries()
    {
        var lists = new System.Collections.Generic.List<int>[1024];
        for (var i = 0; i < lists.Length; i++) lists[i] = new System.Collections.Generic.List<int>();
        for (var entry = 0; entry < Size; entry++)
        for (var row = 0; row < 4; row++)
            lists[row * 256 + (int)((Patterns[entry] >> (row * 8)) & 0xFF)].Add(entry);
        return System.Array.ConvertAll(lists, list => list.ToArray());
    }
